create table if not exists public.game_news (id bigint generated always as identity primary key,title text not null check(char_length(title) between 1 and 90),body text not null check(char_length(body) between 1 and 1200),created_at timestamptz not null default now(),created_by uuid not null references auth.users(id));
alter table public.game_news enable row level security; revoke all on public.game_news from anon,authenticated; grant select on public.game_news to anon,authenticated; drop policy if exists "everyone can read game news" on public.game_news; create policy "everyone can read game news" on public.game_news for select to anon,authenticated using(true); alter table public.game_news replica identity full;
